import sys

def main():
    def count_distinct_sums(x1, y1, x2, y2):
        if x1 == x2 and y1 == y2:
            return 1

        # Calculate the minimum and maximum sums
        min_sum = (x1 + y1 - 1) * (x2 - x1 + y2 - y1) + (x2 - x1) * (x2 - x1 + 1) // 2 + (y2 - y1) * (y2 - y1 + 1) // 2
        max_sum = (x2 + y2 - 1) * (x2 - x1 + y2 - y1) + (x2 - x1) * (x2 - x1 + 1) // 2 + (y2 - y1) * (y2 - y1 + 1) // 2

        # The number of distinct sums is the number of integers from min_sum to max_sum inclusive
        return max_sum - min_sum + 1

    t = int(sys.stdin.readline())
    results = []

    for _ in range(t):
        x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
        result = count_distinct_sums(x1, y1, x2, y2)
        results.append(result)

    for result in results:
        print(result)

